-- MVP pilot recette
-- Patrice = season organizer (canManageComposition on all season events)
INSERT INTO season_organizers (season_id, user_id, granted_by_user_id, granted_at)
SELECT CAST('b0000001-0000-4000-8000-000000000001' AS uuid), CAST('d0000001-0000-4000-8000-000000000022' AS uuid), CAST('d0000001-0000-4000-8000-000000000022' AS uuid), CURRENT_TIMESTAMP
WHERE NOT EXISTS (
  SELECT 1 FROM season_organizers WHERE season_id = CAST('b0000001-0000-4000-8000-000000000001' AS uuid) AND user_id = CAST('d0000001-0000-4000-8000-000000000022' AS uuid)
);

-- Spectacles MVP (titles, dates, minimal role_slots)
-- navigation-only
UPDATE events SET title = '[MVP] 00 · Bandeau navigation', description = 'Spectacle pilote — scénario navigation-only. Aucune composition attendue ; sert à valider le bandeau et les onglets Infos / Dispos / Équipe. Lieu fictif pour recette UI.', location = 'Studio QA HatCast, 1 rue du Test, 59000 Lille', starts_at = '2026-06-03T19:30:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000009-0000-4000-8000-000000000009';
-- draw
UPDATE events SET title = '[MVP] 01 · Tirage pondéré', description = 'Spectacle pilote — tirage pondéré des rôles. Cast réduit à 6 membres avec dispos complètes. Vérifier les probabilités et le feedback visuel post-tirage.', location = 'Salle Recette A, 10 avenue des Tests, 59000 Lille', starts_at = '2026-06-05T20:00:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000014-0000-4000-8000-000000000014';
-- manual
UPDATE events SET title = '[MVP] 02 · Assignation manuelle', description = 'Spectacle pilote — assignation manuelle slot par slot. Prévoir drag-and-drop ou sélection depuis la liste des disponibles. Horaire décalé (21h30 Paris) pour tester l''affichage.', location = 'Salle Recette B, 12 avenue des Tests, 59100 Roubaix', starts_at = '2026-06-07T19:30:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000010-0000-4000-8000-000000000010';
-- awaiting-confirmations
UPDATE events SET title = '[MVP] 03 · Validations en attente', description = 'Spectacle pilote — équipe validée, participations PENDING. Cas nominal pour relances et badges « En attente ». Créneau en milieu de semaine, 22h30 Paris.', location = 'Le Laboratoire, 3 rue des Scénarios, 59000 Lille', starts_at = '2026-06-09T20:30:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000012-0000-4000-8000-000000000012';
-- gaps-to-fill
UPDATE events SET title = '[MVP] 04 · Désistement et compléter', description = 'Spectacle pilote — slot vacant après retrait (Sophie). Tester compléter l''équipe et l''historique des retraits. Matinée pour couvrir un créneau hors heures de pointe.', location = 'Centre Culturel QA, 5 place du Recette, 59200 Tourcoing', starts_at = '2026-06-11T10:30:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000018-0000-4000-8000-000000000018';
-- complete
UPDATE events SET title = '[MVP] 05 · Équipe complète', description = 'Spectacle pilote — référence « Équipe complète » : tous les slots CONFIRMED. État cible après boucle dispos → composition → validations. Apéro fictif à 21h00 Paris.', location = 'La Scène Verte, 20 boulevard du Done, 59000 Lille', starts_at = '2026-06-13T19:00:00Z', template_type = 'cabaret', role_slots = '{"player":3,"mc":1,"dj":1}', updated_at = CURRENT_TIMESTAMP WHERE id = 'c0000020-0000-4000-8000-000000000020';

